            C++

    #include <iostream>
using namespace std;

int gcd(int a, int b)
{
    while (b) {
        int t = b;
        b = a % b;
        a = t;
    }
    return a;
}

int modInverse(int n, int m)
{
    // Check if inverse exists
    if (gcd(n, m) != 1)
        return -1;

    int m0 = m;
    int y = 0, x = 1;

    if (m == 1)
        return 0;

    while (n > 1) {

        // q is quotient
        int q = n / m;
        int t = m;

        // m is remainder now, process same as Euclid's algo
        m = n % m;
        n = t;
        t = y;

        // Update y and x
        y = x - q * y;
        x = t;
    }

    // Make x positive
    if (x < 0)
        x += m0;

    return x;
}

int main()
{
    int n = 3, m = 11;

    cout << modInverse(n, m);

    return 0;
}


